import java.util.Arrays;

class Solution {
    public boolean makesquare(int[] matchsticks) {
            if (matchsticks == null || matchsticks.length < 4) {
                        return false;
                                }

                                        long sum = 0;
                                                for (int stick : matchsticks) {
                                                            sum += stick;
                                                                    }

                                                                            if (sum % 4 != 0) {
                                                                                        return false;
                                                                                                }

                                                                                                        int target = (int) (sum / 4);

                                                                                                                // Sort ascending, then reverse to descending to prune branches early
                                                                                                                        Arrays.sort(matchsticks);
                                                                                                                                reverse(matchsticks);

                                                                                                                                        if (matchsticks[0] > target) {
                                                                                                                                                    return false;
                                                                                                                                                            }

                                                                                                                                                                    int[] sides = new int[4];
                                                                                                                                                                            return backtrack(matchsticks, 0, sides, target);
                                                                                                                                                                                }

                                                                                                                                                                                    private boolean backtrack(int[] matchsticks, int index, int[] sides, int target) {
                                                                                                                                                                                            if (index == matchsticks.length) {
                                                                                                                                                                                                        return sides[0] == target && sides[1] == target && sides[2] == target && sides[3] == target;
                                                                                                                                                                                                                }

                                                                                                                                                                                                                        int current = matchsticks[index];

                                                                                                                                                                                                                                for (int i = 0; i < 4; i++) {
                                                                                                                                                                                                                                            if (sides[i] + current <= target) {
                                                                                                                                                                                                                                                            sides[i] += current;
                                                                                                                                                                                                                                                                            if (backtrack(matchsticks, index + 1, sides, target)) {
                                                                                                                                                                                                                                                                                                return true;
                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                sides[i] -= current;
                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                        // Pruning: if this side is empty (0), trying subsequent empty sides won't produce a different outcome
                                                                                                                                                                                                                                                                                                                                                                    if (sides[i] == 0) {
                                                                                                                                                                                                                                                                                                                                                                                    break;
                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                return false;
                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                        private void reverse(int[] array) {
                                                                                                                                                                                                                                                                                                                                                                                                                                int i = 0, j = array.length - 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                        while (i < j) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                    int temp = array[i];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                array[i] = array[j];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            array[j] = temp;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        i++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    j--;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }